    for i in range(len(sides)):
        if sides[i] >= sum(sides) - sides[i]:
            return False
    return True

def polygon_area(sides):
    # Calculate the area of a polygon using Brahmagupta's formula for cyclic quadrilaterals
    # or Heron's formula for triangles
    n = len(sides)
    if n == 3:
        # Triangle
        a, b, c = sides
        s = (a + b + c) / 2
        return math.sqrt(s * (s - a) * (s - b) * (s - c))
    elif n == 4:
        # Quadrilateral
        a, b, c, d = sides
        s = (a + b + c + d) / 2
        return math.sqrt((s - a) * (s - b) * (s - c) * (s - d))
    else:
        # For polygons with more than 4 sides, we can approximate using the Shoelace formula
        x = [0] * n
        y = [0] * n
        for i in range(n):
            x[i] = sides[i] * math.cos(2 * math.pi * i / n)
            y[i] = sides[i] * math.sin(2 * math.pi * i / n)
        area = 0.5 * abs(sum(x[i] * y[(i + 1) % n] - y[i] * x[(i + 1) % n] for i in range(n)))
        return area

